with base as (select *, substring(txn_type, 1, 4) txn_type_prefix, coalesce(amount, 0) amount_filled from transactions where txn_time >= to_timestamp('2023-04-19 21:00:00')) select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, amount_filled from (select *, row_number() over (partition by account_id, merchant order by amount_filled desc nulls first, id) as dedup_rank from base) ranked where dedup_rank = 1
